using System.Collections.Immutable;

using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;

namespace Gori.CompressedStatics.CSharp;

public sealed partial class CSharpRewriter
{
    /// <summary>
    /// Handles the rewriting of the following Rewriter options:
    /// <list type="bullet">
    /// <item><see cref="CSharpRewriterOptions.RewritePublicToInternal"/>,</item>
    /// <item><see cref="CSharpRewriterOptions.AddAutoGeneratedAttribute"/>,</item>
    /// <item><see cref="CSharpRewriterOptions.AddEmbeddedAttribute"/>,</item>
    /// <item><see cref="CSharpRewriterOptions.RewriteTypeNames"/>.</item>
    /// </list>
    /// </summary>
    /// <param name="rewriter">The rewriter that provides rewrite options and configuration.</param>
    /// <param name="compilation">The compilation used to resolve symbols and generated-code metadata.</param>
    /// <param name="semanticModel">The semantic model used to resolve declared symbols.</param>
    /// <param name="root">The compilation unit used to determine the source line-ending style.</param>
    /// <param name="issues">The collection for rewrite issues.</param>
    /// <param name="cancellationToken">The token used to cancel rewriting.</param>
    private sealed partial class ScopedRewriter(
        CSharpRewriter rewriter,
        Compilation compilation,
        SemanticModel semanticModel,
        CompilationUnitSyntax root,
        List<RewriteIssue> issues,
        CancellationToken cancellationToken) : CSharpSyntaxRewriter
    {
        private readonly CSharpRewriter rewriter = rewriter;
        private readonly SemanticModel semanticModel = semanticModel;
        private readonly List<RewriteIssue> issues = issues;
        private readonly CancellationToken cancellationToken = cancellationToken;
        private readonly RewriterConfiguration configuration = rewriter.Configuration ?? RewriterConfiguration.Empty;
        private readonly HashSet<SyntaxNode> unsupportedMappingReferences = [];
        private readonly List<(Microsoft.CodeAnalysis.Text.TextSpan Span, ImmutableArray<Microsoft.CodeAnalysis.Text.TextSpan> TypeArguments, string Reference, string Destination)> handledReferences = [];
        private readonly string lineEnding = root.ToFullString().Contains("\r\n", StringComparison.Ordinal) ? "\r\n" : "\n";
        private readonly AttributeSyntax? generatedCodeAttribute = rewriter.AddAutoGeneratedAttribute
                ? CreateAttribute("global::System.CodeDom.Compiler.GeneratedCode", compilation.Assembly.Identity.Name, compilation.Assembly.Identity.Version.ToString())
                : null;

        public override SyntaxNode? Visit(SyntaxNode? node)
        {
            cancellationToken.ThrowIfCancellationRequested();
            if (node is not null && node.AncestorsAndSelf().Any(unsupportedMappingReferences.Contains))
            {
                return node;
            }

            if (node is not BaseTypeDeclarationSyntax and not DelegateDeclarationSyntax
                || semanticModel.GetDeclaredSymbol(node, cancellationToken) is not INamedTypeSymbol symbol)
            {
                return rewriter.RewriteTypeNames && node is NameSyntax name ? RewriteName(name) : base.Visit(node);
            }

            SyntaxNode? visited = base.Visit(node);

            // If the type is nested, no modifications required.
            if (symbol.ContainingType is not null)
            {
                return visited;
            }

            // Add GeneratedCode and Embedded attributes to top-level types if configured to do so.
            // Also make public types internal if configured to do so.
            return visited switch
            {
                BaseTypeDeclarationSyntax declaration => AddTypeAttributes(
                    declaration.WithModifiers(rewriter.RewritePublicToInternal ? MakeInternal(declaration.Modifiers) : declaration.Modifiers),
                    declaration.AttributeLists,
                    generatedCodeAttribute,
                    rewriter.AddEmbeddedAttribute,
                    lineEnding),

                DelegateDeclarationSyntax declaration => AddTypeAttributes(
                    declaration.WithModifiers(rewriter.RewritePublicToInternal ? MakeInternal(declaration.Modifiers) : declaration.Modifiers),
                    declaration.AttributeLists,
                    generatedCodeAttribute,
                    rewriter.AddEmbeddedAttribute,
                    lineEnding),

                _ => visited,
            };
        }
    }
}
